#include "myplanetsim/diagnostics/dry_hydrostatic_diagnostics.hpp"
#include <algorithm>
#include <limits>
namespace mps {
DryHydrostaticDiagnostics diagnose_dry_hydrostatic_budgets(const CubedSphereGrid& grid,const DryHydrostaticState&s,const DryHydrostaticDerived&d,const PlanetParameters&p){DryHydrostaticDiagnostics x{0,0,0,0,0,std::numeric_limits<Real>::infinity(),-std::numeric_limits<Real>::infinity(),std::numeric_limits<Real>::infinity(),-std::numeric_limits<Real>::infinity()};const Real cv=p.heat_capacity_cp_j_kg_k-p.gas_constant_j_kg_k;for(std::size_t c=0;c<d.cells;++c){auto area=grid.cells()[c].area_m2;auto pos=p.radius_m*grid.cells()[c].center;x.minimum_surface_pressure_pa=std::min(x.minimum_surface_pressure_pa,s.surface_pressure_pa[c]);x.maximum_surface_pressure_pa=std::max(x.maximum_surface_pressure_pa,s.surface_pressure_pa[c]);for(std::size_t k=0;k<d.levels;++k){auto n=dry_hydrostatic_offset(c,k,d.levels);auto mass=area*d.air_mass_kg_m2[n];x.dry_mass_kg+=mass;x.potential_temperature_mass_k_kg+=area*s.potential_temperature_mass_k_kg_m2[n];x.tracer_mass_kg+=area*s.tracer_mass_kg_m2[n];x.total_energy_j+=mass*(.5*norm_squared(d.velocity_m_s[n])+cv*d.temperature_k[n]+d.geopotential_m2_s2[n]);x.axial_angular_momentum_kg_m2_s+=mass*(cross(pos,d.velocity_m_s[n]).z+p.rotation_rate_rad_s*(pos.x*pos.x+pos.y*pos.y));x.minimum_temperature_k=std::min(x.minimum_temperature_k,d.temperature_k[n]);x.maximum_temperature_k=std::max(x.maximum_temperature_k,d.temperature_k[n]);}}return x;}
}
